DROP FUNCTION IF EXISTS nexus.plain_search_384(nexus.vector, text[], jsonb, text, int); DROP FUNCTION IF EXISTS nexus.plain_search_768(nexus.vector, text[], jsonb, text, int); DROP FUNCTION IF EXISTS nexus.plain_search_1024(nexus.vector, text[], jsonb, text, int); DROP FUNCTION IF EXISTS nexus.text_gated_search_hnsw_first_384(nexus.vector, text, text[], jsonb, text, int); DROP FUNCTION IF EXISTS nexus.text_gated_search_hnsw_first_768(nexus.vector, text, text[], jsonb, text, int); DROP FUNCTION IF EXISTS nexus.text_gated_search_hnsw_first_1024(nexus.vector, text, text[], jsonb, text, int); DROP FUNCTION IF EXISTS nexus.text_gated_search_by_chash_384(nexus.vector, bytea[], text[], jsonb, text, int); DROP FUNCTION IF EXISTS nexus.text_gated_search_by_chash_768(nexus.vector, bytea[], text[], jsonb, text, int); DROP FUNCTION IF EXISTS nexus.text_gated_search_by_chash_1024(nexus.vector, bytea[], text[], jsonb, text, int); DROP FUNCTION IF EXISTS nexus.search_metadata_scoped_384(nexus.vector, text[], text, text, int, text, text, jsonb, int); DROP FUNCTION IF EXISTS nexus.search_metadata_scoped_768(nexus.vector, text[], text, text, int, text, text, jsonb, int); DROP FUNCTION IF EXISTS nexus.search_metadata_scoped_1024(nexus.vector, text[], text, text, int, text, text, jsonb, int); DROP FUNCTION IF EXISTS nexus.search_aspect_scoped_384(nexus.vector, text[], text, text, float8, jsonb, int); DROP FUNCTION IF EXISTS nexus.search_aspect_scoped_768(nexus.vector, text[], text, text, float8, jsonb, int); DROP FUNCTION IF EXISTS nexus.search_aspect_scoped_1024(nexus.vector, text[], text, text, float8, jsonb, int); DROP FUNCTION IF EXISTS nexus.search_graph_hop_384(nexus.vector, text[], text[], text, int, text, jsonb, int); DROP FUNCTION IF EXISTS nexus.search_graph_hop_768(nexus.vector, text[], text[], text, int, text, jsonb, int); DROP FUNCTION IF EXISTS nexus.search_graph_hop_1024(nexus.vector, text[], text[], text, int, text, jsonb, int); DROP FUNCTION IF EXISTS nexus.search_topic_scoped_384(nexus.vector, text, text, int); DROP FUNCTION IF EXISTS nexus.search_topic_scoped_768(nexus.vector, text, text, int); DROP FUNCTION IF EXISTS nexus.search_topic_scoped_1024(nexus.vector, text, text, int); DROP FUNCTION IF EXISTS nexus.taxonomy_ann_query_384(nexus.vector, text, boolean, int); DROP FUNCTION IF EXISTS nexus.taxonomy_ann_query_768(nexus.vector, text, boolean, int); DROP FUNCTION IF EXISTS nexus.taxonomy_ann_query_1024(nexus.vector, text, boolean, int); DROP FUNCTION IF EXISTS nexus.assign_from_chashes_384(text, text[], boolean); DROP FUNCTION IF EXISTS nexus.assign_from_chashes_768(text, text[], boolean); DROP FUNCTION IF EXISTS nexus.assign_from_chashes_1024(text, text[], boolean); DROP FUNCTION IF EXISTS nexus.cross_preview_384(text, text[]); DROP FUNCTION IF EXISTS nexus.cross_preview_768(text, text[]); DROP FUNCTION IF EXISTS nexus.cross_preview_1024(text, text[]);
CREATE OR REPLACE FUNCTION nexus.plain_search_384( p_query nexus.vector(384), p_collections text[], p_where jsonb, p_where_path text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_384 IS NOT NULL AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.plain_search_768( p_query nexus.vector(768), p_collections text[], p_where jsonb, p_where_path text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_768 IS NOT NULL AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.plain_search_1024( p_query nexus.vector(1024), p_collections text[], p_where jsonb, p_where_path text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_1024 IS NOT NULL AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.text_gated_search_hnsw_first_384( p_query nexus.vector(384), p_query_text text, p_collections text[], p_where jsonb, p_where_path text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_384 IS NOT NULL AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
