CREATE OR REPLACE FUNCTION nexus.text_gated_search_by_chash_384( p_query nexus.vector(384), p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_384 IS NOT NULL AND c.chash = ANY(p_chashes) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.text_gated_search_by_chash_768( p_query nexus.vector(768), p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_768 IS NOT NULL AND c.chash = ANY(p_chashes) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.text_gated_search_by_chash_1024( p_query nexus.vector(1024), p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_1024 IS NOT NULL AND c.chash = ANY(p_chashes) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_metadata_scoped_384( p_query nexus.vector(384), p_collections text[], p_content_type text, p_author text, p_year int, p_corpus text, p_subtree text, p_where jsonb, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_content_type IS NULL OR d.content_type = p_content_type) AND (p_author IS NULL OR d.author ILIKE '%' || p_author || '%') AND (p_year IS NULL OR d.year = p_year) AND (p_corpus IS NULL OR d.corpus = p_corpus) AND d.alias_of = '' AND (p_subtree IS NULL OR d.tumbler LIKE p_subtree || '.%') AND (p_where IS NULL OR c.metadata @> p_where) AND c.embedding_384 IS NOT NULL ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_metadata_scoped_768( p_query nexus.vector(768), p_collections text[], p_content_type text, p_author text, p_year int, p_corpus text, p_subtree text, p_where jsonb, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_content_type IS NULL OR d.content_type = p_content_type) AND (p_author IS NULL OR d.author ILIKE '%' || p_author || '%') AND (p_year IS NULL OR d.year = p_year) AND (p_corpus IS NULL OR d.corpus = p_corpus) AND d.alias_of = '' AND (p_subtree IS NULL OR d.tumbler LIKE p_subtree || '.%') AND (p_where IS NULL OR c.metadata @> p_where) AND c.embedding_768 IS NOT NULL ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_metadata_scoped_1024( p_query nexus.vector(1024), p_collections text[], p_content_type text, p_author text, p_year int, p_corpus text, p_subtree text, p_where jsonb, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_content_type IS NULL OR d.content_type = p_content_type) AND (p_author IS NULL OR d.author ILIKE '%' || p_author || '%') AND (p_year IS NULL OR d.year = p_year) AND (p_corpus IS NULL OR d.corpus = p_corpus) AND d.alias_of = '' AND (p_subtree IS NULL OR d.tumbler LIKE p_subtree || '.%') AND (p_where IS NULL OR c.metadata @> p_where) AND c.embedding_1024 IS NOT NULL ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_aspect_scoped_384( p_query nexus.vector(384), p_collections text[], p_field text, p_pattern text, p_min_confidence float8, p_where jsonb, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id JOIN nexus.document_aspects a ON a.tenant_id = d.tenant_id AND a.doc_id = d.tumbler WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND d.alias_of = '' AND c.embedding_384 IS NOT NULL AND (p_where IS NULL OR c.metadata @> p_where) AND (p_min_confidence IS NULL OR a.confidence >= p_min_confidence) AND (p_field IS NULL OR CASE p_field WHEN 'problem_formulation' THEN a.problem_formulation WHEN 'proposed_method' THEN a.proposed_method WHEN 'experimental_datasets' THEN a.experimental_datasets WHEN 'experimental_baselines' THEN a.experimental_baselines WHEN 'experimental_results' THEN a.experimental_results END ILIKE '%' || p_pattern || '%') ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_aspect_scoped_768( p_query nexus.vector(768), p_collections text[], p_field text, p_pattern text, p_min_confidence float8, p_where jsonb, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id JOIN nexus.document_aspects a ON a.tenant_id = d.tenant_id AND a.doc_id = d.tumbler WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND d.alias_of = '' AND c.embedding_768 IS NOT NULL AND (p_where IS NULL OR c.metadata @> p_where) AND (p_min_confidence IS NULL OR a.confidence >= p_min_confidence) AND (p_field IS NULL OR CASE p_field WHEN 'problem_formulation' THEN a.problem_formulation WHEN 'proposed_method' THEN a.proposed_method WHEN 'experimental_datasets' THEN a.experimental_datasets WHEN 'experimental_baselines' THEN a.experimental_baselines WHEN 'experimental_results' THEN a.experimental_results END ILIKE '%' || p_pattern || '%') ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_aspect_scoped_1024( p_query nexus.vector(1024), p_collections text[], p_field text, p_pattern text, p_min_confidence float8, p_where jsonb, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id JOIN nexus.document_aspects a ON a.tenant_id = d.tenant_id AND a.doc_id = d.tumbler WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND d.alias_of = '' AND c.embedding_1024 IS NOT NULL AND (p_where IS NULL OR c.metadata @> p_where) AND (p_min_confidence IS NULL OR a.confidence >= p_min_confidence) AND (p_field IS NULL OR CASE p_field WHEN 'problem_formulation' THEN a.problem_formulation WHEN 'proposed_method' THEN a.proposed_method WHEN 'experimental_datasets' THEN a.experimental_datasets WHEN 'experimental_baselines' THEN a.experimental_baselines WHEN 'experimental_results' THEN a.experimental_results END ILIKE '%' || p_pattern || '%') ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_graph_hop_384( p_query nexus.vector(384), p_seeds text[], p_collections text[], p_link_type text, p_depth int, p_direction text, p_where jsonb, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ WITH RECURSIVE reach(tumbler, d) AS ( SELECT s, 0 FROM unnest(p_seeds) AS s UNION SELECT CASE WHEN l.from_tumbler = r.tumbler THEN l.to_tumbler ELSE l.from_tumbler END, r.d + 1 FROM reach r JOIN nexus.catalog_links l ON ((p_direction = 'out' AND l.from_tumbler = r.tumbler) OR (p_direction = 'in' AND l.to_tumbler = r.tumbler) OR (p_direction = 'both' AND (l.from_tumbler = r.tumbler OR l.to_tumbler = r.tumbler))) JOIN nexus.catalog_documents fd ON fd.tumbler = l.from_tumbler AND fd.deleted_at IS NULL JOIN nexus.catalog_documents td ON td.tumbler = l.to_tumbler AND td.deleted_at IS NULL WHERE r.d < p_depth AND (p_link_type IS NULL OR l.link_type = p_link_type) ), reached AS (SELECT DISTINCT tumbler FROM reach) SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id JOIN reached rd ON rd.tumbler = d.tumbler WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_where IS NULL OR c.metadata @> p_where) AND c.embedding_384 IS NOT NULL ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_graph_hop_768( p_query nexus.vector(768), p_seeds text[], p_collections text[], p_link_type text, p_depth int, p_direction text, p_where jsonb, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ WITH RECURSIVE reach(tumbler, d) AS ( SELECT s, 0 FROM unnest(p_seeds) AS s UNION SELECT CASE WHEN l.from_tumbler = r.tumbler THEN l.to_tumbler ELSE l.from_tumbler END, r.d + 1 FROM reach r JOIN nexus.catalog_links l ON ((p_direction = 'out' AND l.from_tumbler = r.tumbler) OR (p_direction = 'in' AND l.to_tumbler = r.tumbler) OR (p_direction = 'both' AND (l.from_tumbler = r.tumbler OR l.to_tumbler = r.tumbler))) JOIN nexus.catalog_documents fd ON fd.tumbler = l.from_tumbler AND fd.deleted_at IS NULL JOIN nexus.catalog_documents td ON td.tumbler = l.to_tumbler AND td.deleted_at IS NULL WHERE r.d < p_depth AND (p_link_type IS NULL OR l.link_type = p_link_type) ), reached AS (SELECT DISTINCT tumbler FROM reach) SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id JOIN reached rd ON rd.tumbler = d.tumbler WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_where IS NULL OR c.metadata @> p_where) AND c.embedding_768 IS NOT NULL ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_graph_hop_1024( p_query nexus.vector(1024), p_seeds text[], p_collections text[], p_link_type text, p_depth int, p_direction text, p_where jsonb, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ WITH RECURSIVE reach(tumbler, d) AS ( SELECT s, 0 FROM unnest(p_seeds) AS s UNION SELECT CASE WHEN l.from_tumbler = r.tumbler THEN l.to_tumbler ELSE l.from_tumbler END, r.d + 1 FROM reach r JOIN nexus.catalog_links l ON ((p_direction = 'out' AND l.from_tumbler = r.tumbler) OR (p_direction = 'in' AND l.to_tumbler = r.tumbler) OR (p_direction = 'both' AND (l.from_tumbler = r.tumbler OR l.to_tumbler = r.tumbler))) JOIN nexus.catalog_documents fd ON fd.tumbler = l.from_tumbler AND fd.deleted_at IS NULL JOIN nexus.catalog_documents td ON td.tumbler = l.to_tumbler AND td.deleted_at IS NULL WHERE r.d < p_depth AND (p_link_type IS NULL OR l.link_type = p_link_type) ), reached AS (SELECT DISTINCT tumbler FROM reach) SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, encode(c.chash, 'hex'), c.retention FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id JOIN reached rd ON rd.tumbler = d.tumbler WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_where IS NULL OR c.metadata @> p_where) AND c.embedding_1024 IS NOT NULL ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_topic_scoped_384( p_query nexus.vector(384), p_topic_label text, p_collection text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.retention FROM nexus.chunks c JOIN nexus.topic_assignments ta ON ta.tenant_id = c.tenant_id AND ta.doc_id = c.chash JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = p_collection AND t.collection = p_collection AND t.label = p_topic_label AND c.embedding_384 IS NOT NULL AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_topic_scoped_768( p_query nexus.vector(768), p_topic_label text, p_collection text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, c.retention FROM nexus.chunks c JOIN nexus.topic_assignments ta ON ta.tenant_id = c.tenant_id AND ta.doc_id = c.chash JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = p_collection AND t.collection = p_collection AND t.label = p_topic_label AND c.embedding_768 IS NOT NULL AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_topic_scoped_1024( p_query nexus.vector(1024), p_topic_label text, p_collection text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, c.retention FROM nexus.chunks c JOIN nexus.topic_assignments ta ON ta.tenant_id = c.tenant_id AND ta.doc_id = c.chash JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = p_collection AND t.collection = p_collection AND t.label = p_topic_label AND c.embedding_1024 IS NOT NULL AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.taxonomy_ann_query_384( p_embedding nexus.vector(384), p_collection text, p_cross_collection boolean, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(topic_id bigint, distance float8) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT topic_id, (embedding_384 OPERATOR(nexus.<=>) p_embedding)::float8 AS distance FROM nexus.taxonomy_centroids WHERE embedding_model = p_embedding_model AND tenant_id = p_tenant AND embedding_384 IS NOT NULL AND (CASE WHEN p_cross_collection THEN collection <> p_collection ELSE collection = p_collection END) ORDER BY embedding_384 OPERATOR(nexus.<=>) p_embedding, topic_id ASC LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.taxonomy_ann_query_768( p_embedding nexus.vector(768), p_collection text, p_cross_collection boolean, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(topic_id bigint, distance float8) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT topic_id, (embedding_768 OPERATOR(nexus.<=>) p_embedding)::float8 AS distance FROM nexus.taxonomy_centroids WHERE embedding_model = p_embedding_model AND tenant_id = p_tenant AND embedding_768 IS NOT NULL AND (CASE WHEN p_cross_collection THEN collection <> p_collection ELSE collection = p_collection END) ORDER BY embedding_768 OPERATOR(nexus.<=>) p_embedding, topic_id ASC LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.taxonomy_ann_query_1024( p_embedding nexus.vector(1024), p_collection text, p_cross_collection boolean, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(topic_id bigint, distance float8) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT topic_id, (embedding_1024 OPERATOR(nexus.<=>) p_embedding)::float8 AS distance FROM nexus.taxonomy_centroids WHERE embedding_model = p_embedding_model AND tenant_id = p_tenant AND embedding_1024 IS NOT NULL AND (CASE WHEN p_cross_collection THEN collection <> p_collection ELSE collection = p_collection END) ORDER BY embedding_1024 OPERATOR(nexus.<=>) p_embedding, topic_id ASC LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.assign_from_chashes_384(p_collection text, p_chashes text[], p_cross_collection boolean, p_embedding_model text, p_tenant text) RETURNS TABLE(chash text, topic_id bigint, similarity double precision) LANGUAGE plpgsql SET plan_cache_mode = force_custom_plan AS $function$ #variable_conflict use_column BEGIN IF p_cross_collection THEN -- Sam's standing rule for this RDR: one fail-loud path for every -- stub-insert, nothing mints a catalog_collections row from a name -- any more. Post-nexus-ft04v.7, chunks_collection_fk already requires -- p_collection to be registered before any chunk can exist under it, -- so if the batch below finds rows at all, the row is guaranteed -- present -- this guard only ever fires on a genuinely absent -- registration (a caller naming a collection with zero chunks), and -- names the remedy instead of silently minting the row this branch -- used to stub-insert here. IF NOT EXISTS ( SELECT 1 FROM nexus.catalog_collections WHERE tenant_id = current_setting('nexus.tenant', true) AND name = p_collection AND embedding_model = p_embedding_model ) THEN RAISE EXCEPTION 'assign_from_chashes_384: collection % is not registered for tenant % -- register it first via POST /v1/catalog/collections/upsert', p_collection, current_setting('nexus.tenant', true) USING ERRCODE = 'foreign_key_violation'; END IF;
-- nexus-f3yxx: the LATERAL's recall settings, transaction-local. -- NOT a function-level SET clause: CREATE FUNCTION ... SET hnsw.* -- fails with 'permission denied to set parameter' for a -- non-superuser migration role when pgvector's library is not yet -- loaded in that session (hnsw.* is then an unknown placeholder), -- which is every production boot (candidate-migration leg, -- 2026-09-25). set_config is allowed to any role. is_local=true -- scopes it to this transaction, which since the rework is the -- cross pass alone. PERFORM set_config('hnsw.iterative_scan', 'strict_order', true); PERFORM set_config('hnsw.ef_search', '400', true);
-- nexus-swam7: pin the ACCESS PATH itself, not just the ANN recall -- settings. At ef_search=400 the planner's own cost model prefers a -- per-chunk Seq Scan + top-N Sort over taxonomy_centroids until -- ~8,000 centroids/dim (T2 nexus/p02-hnsw-incremental-recall- -- 2026-09-25); below that, this pin is what makes the "measured -- equal to exact at ef400" claim (taxonomy-018's header) actually -- true, by forcing the HNSW index scan the recall claim assumes. -- Legal as a function-level SET (these are core GUCs, unlike -- hnsw.*), but kept as set_config for consistency with the two -- calls above -- see this changeset's own header for the full -- reasoning and the measurement that verified each pin's effect. PERFORM set_config('enable_seqscan', 'off', true); PERFORM set_config('enable_sort', 'off', true);
RETURN QUERY WITH batch AS ( SELECT c.chash AS b_chash, c.embedding_384 AS b_emb, c.embedding_model AS b_model FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = p_collection AND c.embedding_384 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ), nearest AS ( SELECT encode(b.b_chash, 'hex') AS m_chash, b.b_chash AS m_chash_bytes, b.b_model AS m_model, n.n_topic_id AS m_topic_id, (1 - n.n_dist)::double precision AS m_sim FROM batch b CROSS JOIN LATERAL ( SELECT ct.topic_id AS n_topic_id, (ct.embedding_384 OPERATOR(nexus.<=>) b.b_emb) AS n_dist FROM nexus.taxonomy_centroids ct WHERE ct.embedding_model = p_embedding_model AND ct.tenant_id = p_tenant AND ct.collection <> p_collection AND ct.embedding_384 IS NOT NULL ORDER BY ct.embedding_384 OPERATOR(nexus.<=>) b.b_emb, ct.topic_id ASC LIMIT 1 ) n ), persisted AS ( -- RDR-225: embedding_model is the chunk's own (it is part of the four-column chunk foreign key). INSERT INTO nexus.topic_assignments AS ta (tenant_id, doc_id, topic_id, assigned_by, similarity, assigned_at, source_collection, embedding_model) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'projection', n.m_sim, now(), p_collection, n.m_model FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO UPDATE SET similarity = GREATEST(COALESCE(ta.similarity, -1.0), EXCLUDED.similarity), assigned_at = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.assigned_at ELSE ta.assigned_at END, source_collection = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.source_collection ELSE ta.source_collection END, -- the model moves with the source collection: the pair is one chunk reference. embedding_model = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.embedding_model ELSE ta.embedding_model END, assigned_by = 'projection' RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, n.m_sim FROM nearest n; ELSE RETURN QUERY WITH nearest AS ( SELECT DISTINCT ON (c.chash) encode(c.chash, 'hex') AS m_chash, c.chash AS m_chash_bytes, c.embedding_model AS m_model, ct.topic_id AS m_topic_id, (1 - (c.embedding_384 OPERATOR(nexus.<=>) ct.embedding_384))::double precision AS m_sim FROM nexus.chunks c JOIN nexus.taxonomy_centroids ct ON ct.embedding_model = p_embedding_model AND ct.tenant_id = p_tenant AND ct.collection = p_collection AND ct.embedding_384 IS NOT NULL WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = p_collection AND c.embedding_384 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ORDER BY c.chash, (c.embedding_384 OPERATOR(nexus.<=>) ct.embedding_384) ASC, ct.topic_id ASC ), persisted AS ( INSERT INTO nexus.topic_assignments (tenant_id, doc_id, topic_id, assigned_by, source_collection, embedding_model) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'centroid', p_collection, n.m_model FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO NOTHING RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, NULL::double precision FROM nearest n; END IF; END; $function$;
