DO $do$ DECLARE definer boolean; BEGIN SELECT count(*) = 3 INTO definer FROM pg_catalog.pg_proc p WHERE p.pronamespace = 'nexus'::pg_catalog.regnamespace AND p.proname IN ('text_gate_probe_384', 'text_gate_probe_768', 'text_gate_probe_1024') AND p.prosecdef; DROP FUNCTION IF EXISTS nexus.text_gate_probe_384(text, text[], jsonb, text, int); DROP FUNCTION IF EXISTS nexus.text_gate_probe_768(text, text[], jsonb, text, int); DROP FUNCTION IF EXISTS nexus.text_gate_probe_1024(text, text[], jsonb, text, int); IF definer THEN EXECUTE $f$CREATE OR REPLACE FUNCTION nexus.text_gate_probe_384( p_text text, p_collections text[], p_where jsonb, p_where_path text, p_cap int, p_embedding_model text, p_tenant text ) RETURNS SETOF bytea LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp SET plan_cache_mode = force_custom_plan AS $$ BEGIN RETURN QUERY SELECT c.chash FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.tenant_id = NULLIF(pg_catalog.current_setting('nexus.tenant', true), '') AND c.collection = ANY(p_collections) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ pg_catalog.plainto_tsquery('english', p_text) OR p_text OPERATOR(nexus.<%) c.chunk_text) LIMIT p_cap; END $$$f$; EXECUTE $f$CREATE OR REPLACE FUNCTION nexus.text_gate_probe_768( p_text text, p_collections text[], p_where jsonb, p_where_path text, p_cap int, p_embedding_model text, p_tenant text ) RETURNS SETOF bytea LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp SET plan_cache_mode = force_custom_plan AS $$ BEGIN RETURN QUERY SELECT c.chash FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.tenant_id = NULLIF(pg_catalog.current_setting('nexus.tenant', true), '') AND c.collection = ANY(p_collections) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ pg_catalog.plainto_tsquery('english', p_text) OR p_text OPERATOR(nexus.<%) c.chunk_text) LIMIT p_cap; END $$$f$; EXECUTE $f$CREATE OR REPLACE FUNCTION nexus.text_gate_probe_1024( p_text text, p_collections text[], p_where jsonb, p_where_path text, p_cap int, p_embedding_model text, p_tenant text ) RETURNS SETOF bytea LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp SET plan_cache_mode = force_custom_plan AS $$ BEGIN RETURN QUERY SELECT c.chash FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.tenant_id = NULLIF(pg_catalog.current_setting('nexus.tenant', true), '') AND c.collection = ANY(p_collections) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ pg_catalog.plainto_tsquery('english', p_text) OR p_text OPERATOR(nexus.<%) c.chunk_text) LIMIT p_cap; END $$$f$; REVOKE EXECUTE ON FUNCTION nexus.text_gate_probe_384(text, text[], jsonb, text, int, text, text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nexus.text_gate_probe_384(text, text[], jsonb, text, int, text, text) TO nexus_svc; REVOKE EXECUTE ON FUNCTION nexus.text_gate_probe_768(text, text[], jsonb, text, int, text, text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nexus.text_gate_probe_768(text, text[], jsonb, text, int, text, text) TO nexus_svc; REVOKE EXECUTE ON FUNCTION nexus.text_gate_probe_1024(text, text[], jsonb, text, int, text, text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nexus.text_gate_probe_1024(text, text[], jsonb, text, int, text, text) TO nexus_svc; ELSE EXECUTE $f$CREATE OR REPLACE FUNCTION nexus.text_gate_probe_384( p_text text, p_collections text[], p_where jsonb, p_where_path text, p_cap int, p_embedding_model text, p_tenant text ) RETURNS SETOF bytea LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT c.chash FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.tenant_id = NULLIF(pg_catalog.current_setting('nexus.tenant', true), '') AND c.collection = ANY(p_collections) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ pg_catalog.plainto_tsquery('english', p_text) OR p_text OPERATOR(nexus.<%) c.chunk_text) LIMIT p_cap $$$f$; EXECUTE $f$CREATE OR REPLACE FUNCTION nexus.text_gate_probe_768( p_text text, p_collections text[], p_where jsonb, p_where_path text, p_cap int, p_embedding_model text, p_tenant text ) RETURNS SETOF bytea LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT c.chash FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.tenant_id = NULLIF(pg_catalog.current_setting('nexus.tenant', true), '') AND c.collection = ANY(p_collections) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ pg_catalog.plainto_tsquery('english', p_text) OR p_text OPERATOR(nexus.<%) c.chunk_text) LIMIT p_cap $$$f$; EXECUTE $f$CREATE OR REPLACE FUNCTION nexus.text_gate_probe_1024( p_text text, p_collections text[], p_where jsonb, p_where_path text, p_cap int, p_embedding_model text, p_tenant text ) RETURNS SETOF bytea LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT c.chash FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.tenant_id = NULLIF(pg_catalog.current_setting('nexus.tenant', true), '') AND c.collection = ANY(p_collections) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ pg_catalog.plainto_tsquery('english', p_text) OR p_text OPERATOR(nexus.<%) c.chunk_text) LIMIT p_cap $$$f$; GRANT EXECUTE ON FUNCTION nexus.text_gate_probe_384(text, text[], jsonb, text, int, text, text) TO nexus_svc; GRANT EXECUTE ON FUNCTION nexus.text_gate_probe_768(text, text[], jsonb, text, int, text, text) TO nexus_svc; GRANT EXECUTE ON FUNCTION nexus.text_gate_probe_1024(text, text[], jsonb, text, int, text, text) TO nexus_svc; END IF; END $do$;
DO $post$ DECLARE n int; stale text; BEGIN SELECT count(*) INTO n FROM pg_catalog.pg_proc p WHERE p.pronamespace = 'nexus'::pg_catalog.regnamespace AND p.proname IN ('text_gate_probe_384', 'text_gate_probe_768', 'text_gate_probe_1024'); IF n <> 3 THEN SELECT string_agg(p.proname || '(' || pg_catalog.pg_get_function_identity_arguments(p.oid) || ')', ', ') INTO stale FROM pg_catalog.pg_proc p WHERE p.pronamespace = 'nexus'::pg_catalog.regnamespace AND p.proname IN ('text_gate_probe_384', 'text_gate_probe_768', 'text_gate_probe_1024'); RAISE EXCEPTION 'vectors-031: expected exactly 3 read-path functions (one signature each), found %: %', n, stale; END IF; END $post$;
DO $post$ DECLARE me oid := (SELECT r.oid FROM pg_catalog.pg_roles r WHERE r.rolname = current_user); n_definer int; bad_owner text; BEGIN SELECT count(*) FILTER (WHERE p.prosecdef), string_agg(p.proname, ', ') FILTER (WHERE p.prosecdef AND p.proowner <> me) INTO n_definer, bad_owner FROM pg_catalog.pg_proc p WHERE p.pronamespace = 'nexus'::pg_catalog.regnamespace AND p.proname IN ('text_gate_probe_384', 'text_gate_probe_768', 'text_gate_probe_1024'); IF n_definer NOT IN (0, 3) THEN RAISE EXCEPTION 'vectors-031-2: % of the 3 text_gate_probe functions are SECURITY DEFINER; the three must agree', n_definer; END IF; IF bad_owner IS NOT NULL THEN RAISE EXCEPTION 'vectors-031-2: probe(s) % are SECURITY DEFINER but not owned by the migrating role %', bad_owner, current_user; END IF; END $post$;

